-- Name: add_new_member(character varying, character varying, date, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_new_member(p_first_name character varying, p_last_name character varying, p_birth_date date, p_phone character varying, p_email character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_member_id INTEGER;
BEGIN

        first_name,
        last_name,
        birth_date,
        phone,
        email
    )
    VALUES
    (
        p_first_name,
        p_last_name,
        p_birth_date,
        p_phone,
        p_email
    )
    RETURNING member_id
    INTO new_member_id;

    RETURN new_member_id;

END;
$$;


