--
-- Name: register_membership(integer, integer, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_membership(p_member_id integer, p_membership_id integer, p_start_date date) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE

    membership_duration INTEGER;

BEGIN

    SELECT duration_months
    INTO membership_duration
    FROM memberships
    WHERE membership_id = p_membership_id;

        member_id,
        membership_id,
        start_date,
        end_date
    )
    VALUES
    (
        p_member_id,
        p_membership_id,
        p_start_date,
        p_start_date + (membership_duration || ' month')::INTERVAL
    );

END;
$$;


ALTER FUNCTION public.register_membership(p_member_id integer, p_membership_id integer, p_start_date date) OWNER TO postgres;

--
-- Name: trainer_statistics(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trainer_statistics(p_trainer_id integer) RETURNS TABLE(trainer_name text, sessions_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

    SELECT
        t.first_name || ' ' || t.last_name,
        COUNT(ts.session_id)

    FROM trainers t

    LEFT JOIN training_sessions ts
        ON t.trainer_id = ts.trainer_id

    WHERE t.trainer_id = p_trainer_id

    GROUP BY
        t.first_name,
        t.last_name;

END;
$$;


ALTER FUNCTION public.trainer_statistics(p_trainer_id integer) OWNER TO postgres;

--
-- Name: validate_member_data(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_member_data() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.email IS NOT NULL
       AND NEW.email !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
        RAISE EXCEPTION 'Некоректний email: %', NEW.email
            USING ERRCODE = 'check_violation',
                  HINT = 'Очікуваний формат: name@domain.com';
    END IF;

    IF NEW.phone !~ '^\+?[0-9]{10,15}$' THEN
        RAISE EXCEPTION 'Некоректний телефон: %', NEW.phone
            USING ERRCODE = 'check_violation',
                  HINT = 'Лише цифри (допускається ведучий +), довжина 10-15 символів';
    END IF;

    IF NEW.birth_date < DATE '1900-01-01'
       OR NEW.birth_date > CURRENT_DATE - INTERVAL '5 years' THEN
        RAISE EXCEPTION 'Некоректна дата народження: %', NEW.birth_date
            USING ERRCODE = 'check_violation',
                  HINT = 'Учаснику має бути щонайменше 5 років, дата не раніше 1900-01-01';
    END IF;

    RETURN NEW;
END;
$_$;


