--
-- Name: v_active_memberships; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_active_memberships AS
 SELECT m.member_id,
    m.first_name,
    m.last_name,
    ms.membership_name,
    mm.start_date,
    mm.end_date,
    (mm.end_date - CURRENT_DATE) AS days_left
   FROM ((public.member_memberships mm
     JOIN public.members m ON ((m.member_id = mm.member_id)))
     JOIN public.memberships ms ON ((ms.membership_id = mm.membership_id)))
  WHERE ((CURRENT_DATE >= mm.start_date) AND (CURRENT_DATE <= mm.end_date));


ALTER VIEW public.v_active_memberships OWNER TO postgres;

--
-- Name: v_member_profile; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_member_profile AS
 SELECT m.member_id,
    m.first_name,
    m.last_name,
    m.phone,
    m.email,
    cur.membership_name,
    cur.end_date AS membership_end_date
   FROM (public.members m
     LEFT JOIN LATERAL ( SELECT ms.membership_name,
            mm.end_date
           FROM (public.member_memberships mm
             JOIN public.memberships ms ON ((ms.membership_id = mm.membership_id)))
          WHERE (mm.member_id = m.member_id)
          ORDER BY mm.end_date DESC
         LIMIT 1) cur ON (true));


ALTER VIEW public.v_member_profile OWNER TO postgres;

--
-- Name: v_trainer_workload; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_trainer_workload AS
 SELECT t.trainer_id,
    (((t.first_name)::text || ' '::text) || (t.last_name)::text) AS trainer_name,
    t.specialization,
    count(DISTINCT ts.session_id) AS sessions_count,
    count(a.attendance_id) AS total_visits,
    round(((count(a.attendance_id))::numeric / (NULLIF(count(DISTINCT ts.session_id), 0))::numeric), 1) AS avg_visits_per_session
   FROM ((public.trainers t
     LEFT JOIN public.training_sessions ts ON ((ts.trainer_id = t.trainer_id)))
     LEFT JOIN public.attendance a ON ((a.session_id = ts.session_id)))
  GROUP BY t.trainer_id, t.first_name, t.last_name, t.specialization;


ALTER VIEW public.v_trainer_workload OWNER TO postgres;

